use crate::aap::caps::http_client;
use crate::aap::caps::inference_llm;
use crate::aap::caps::types::{EscalationRequest, ModeratedQuery, PolicyViolation};

struct Node;

/// Percent-encode a string for use as a URL query component (RFC 3986
/// unreserved characters pass through; every other byte becomes %XX).
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len() * 3);
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(query: CustomerQuery) -> ModerationResult {
        // Enrichment fetch, as directed by the graph's author. The result is
        // deliberately not used: the node's output must not change. `fetch`
        // returns transport failures as values, so a down endpoint does not
        // fail the node.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&query.question)
        );
        let _enrichment = http_client::fetch(&url);

        // Ask the model to classify the bounded `question` and route on its
        // one-word verdict.
        let verdict = inference_llm::infer(
            "You are a content-moderation classifier for customer-support \
             messages. Read the user message and reply with exactly one word \
             and nothing else: ALLOW if it is acceptable, VIOLATION if it \
             breaks content policy (abuse, illicit requests, etc.), or \
             ESCALATE if it needs a human (threats of self-harm, legal/safety \
             matters, or anything you are unsure about).",
            &query.question,
            "moderate",
        );

        let tag = verdict.trim().to_ascii_uppercase();

        if tag.starts_with("VIOLATION") {
            ModerationResult::Violation(PolicyViolation {
                reason: "message rejected by content moderation".to_string(),
            })
        } else if tag.starts_with("ESCALATE") {
            ModerationResult::Escalation(EscalationRequest {
                query,
                reason: "message flagged for human review".to_string(),
            })
        } else {
            // ALLOW, or any unrecognised answer, is treated as passing: the
            // query is wrapped unchanged, recording at the type level that
            // moderation has occurred.
            ModerationResult::Ok(ModeratedQuery { query })
        }
    }
}

